import Card from '../../../components/Card';
import {PropertySiteContainer,CardImage,PriceContainer} from './styles';




const PropertySite = () =>{

    const Property = {
        image:"https://www.themoviedb.org/t/p/w533_and_h300_bestv2/jBJWaqoSCiARWtfV0GlqHrcdidd.jpg"
    };

    return(
        <PropertySiteContainer>
        <Card width='70%' height='400px' >            
            <CardImage>
                <img src={Property.image} />
            </CardImage>
            <PriceContainer>
                <p>R$ 256,000</p>
            </PriceContainer>
            

        
     
        </Card>
        </PropertySiteContainer>
     
      
            
           

      
    )
}

export default PropertySite
